liquid:
{%- assign valid = true -%}
{%- assign matches = false -%}
{%- assign inputs = nil -%}
{%- assign hasInputs = apiEaseParameters | has_key: 'liquidParams' -%}
{%- if hasInputs -%}
  {%- assign inputs = apiEaseParameters.liquidParams -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'candidateHandle' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.candidateHandle | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
  {%- if inputs.candidateHandle == '' -%}{%- assign valid = false -%}{%- endif -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'expectedHandle' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.expectedHandle | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
  {%- if inputs.expectedHandle == '' -%}{%- assign valid = false -%}{%- endif -%}
{%- endif -%}
{%- if valid -%}
  {%- if inputs.candidateHandle == inputs.expectedHandle -%}{%- assign matches = true -%}{%- endif -%}
{%- endif -%}
{%- if valid -%}
{"success":true,"matches":{{ matches | json }},"error":null}
{%- else -%}
{"success":false,"matches":false,"error":"candidateHandle and expectedHandle must both be present nonempty strings."}
{%- endif -%}
